def _clean_ip(h):
    if h.startswith('[') and h.endswith(']'):
        return h[1:-1]
    return h


def _is_ip(h):
    h = _clean_ip(h)
    try:
        ipaddress.ip_address(h)
        return True
    except ValueError:
        return False


def is_allowed(host, allowlist):
    """Check an outbound host against the egress allowlist."""
    if not host:
        return False

    # Normalize host
    normalized_host = host.lower()
    if normalized_host.endswith('.'):
        normalized_host = normalized_host[:-1]

    host_is_ip = _is_ip(normalized_host)

    for entry in allowlist:
        if not entry:
            continue
        # Normalize entry
        norm_entry = entry.lower()
        if norm_entry.endswith('.'):
            norm_entry = norm_entry[:-1]

        if host_is_ip:
            # IP literals match only exact entries (after normalization)
            if _clean_ip(normalized_host) == _clean_ip(norm_entry):
                return True
            continue

        # Wildcard match
        if norm_entry.startswith("*."):
            domain_part = norm_entry[2:]
            suffix = "." + domain_part
            if normalized_host.endswith(suffix):
                prefix = normalized_host[:-len(suffix)]
                if prefix and "." not in prefix:
                    return True
        elif norm_entry == "*":
            return True
        elif normalized_host == norm_entry:
            return True

    return False

