newString: """Redact sensitive fields from log events."""
from collections.abc import Mapping


def is_sensitive_key(key):
    if not isinstance(key, str):
        return False
    normalized = key.lower().replace('-', '').replace('_', '')
    keywords = (
        "password",
        "token",
        "key",
        "ssn",
        "secret",
        "cardnumber",
        "creditcard",
        "cardno",
        "cardnum",
        "cvv",
        "cvc",
        "pin",
    )
    return any(keyword in normalized for keyword in keywords)


def mask_value(key, val):
    if not isinstance(key, str):
        return "***"

    normalized = key.lower().replace('-', '').replace('_', '')
    is_card = any(kw in normalized for kw in ("cardnumber", "creditcard", "cardno", "cardnum"))

    if is_card and val is not None:
        val_str = str(val)
        if len(val_str) > 4:
            return "***" + val_str[-4:]
        else:
            return "***" + val_str

    return "***"


def redact(event):
    """Mask sensitive fields in a log event."""
    if isinstance(event, Mapping):
        out = {}
        for key, val in event.items():
            if is_sensitive_key(key):
                out[key] = mask_value(key, val)
            else:
                out[key] = redact(val)
        if type(event) is not dict:
            try:
                out = type(event)(out)
            except Exception:
                pass
        return out
    elif isinstance(event, list):
        return [redact(item) for item in event]
    elif isinstance(event, tuple):
        return tuple(redact(item) for item in event)
    elif isinstance(event, set):
        return {redact(item) for item in event}
    else:
        return event
