content: """SLA downtime accounting."""
from datetime import datetime, timedelta, timezone


def _t(s):
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
    return dt


def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    # 1. Parse all incidents into (start, end) datetime pairs
    incident_intervals = []
    for inc in incidents:
        start_dt = _t(inc["start"])
        end_dt = _t(inc["end"])
        if end_dt > start_dt:
            incident_intervals.append((start_dt, end_dt))

    # 2. Merge overlapping or adjacent incident intervals
    incident_intervals.sort(key=lambda x: x[0])
    merged_incidents = []
    for start, end in incident_intervals:
        if not merged_incidents:
            merged_incidents.append((start, end))
        else:
            last_start, last_end = merged_incidents[-1]
            if start <= last_end:
                merged_incidents[-1] = (last_start, max(last_end, end))
            else:
                merged_incidents.append((start, end))

    # 3. Filter and merge valid maintenance windows (announced at least 24h in advance)
    maint_intervals = []
    for m in maintenance:
        announced_at = m.get("announced_at")
        if not announced_at:
            continue
        m_start = _t(m["start"])
        m_end = _t(m["end"])
        if m_end <= m_start:
            continue
        # Check if announced at least 24 hours in advance of the maintenance start
        if m_start - _t(announced_at) >= timedelta(hours=24):
            maint_intervals.append((m_start, m_end))

    maint_intervals.sort(key=lambda x: x[0])
    merged_maint = []
    for start, end in maint_intervals:
        if not merged_maint:
            merged_maint.append((start, end))
        else:
            last_start, last_end = merged_maint[-1]
            if start <= last_end:
                merged_maint[-1] = (last_start, max(last_end, end))
            else:
                merged_maint.append((start, end))

    # 4. Calculate total downtime minutes
    total_seconds = 0.0
    for start, end in merged_incidents:
        # Ignore sub-minute blips (less than 60 seconds)
        if (end - start).total_seconds() < 60.0:
            continue
        span = (end - start).total_seconds()
        for m_start, m_end in merged_maint:
            lo = max(start, m_start)
            hi = min(end, m_end)
            if hi > lo:
                span -= (hi - lo).total_seconds()
        total_seconds += span

    return total_seconds / 60.0

