content: """Order lifecycle state machine."""


class InvalidTransition(Exception):
    """Raised when an order may not move to the requested state."""


_ORDER = ["pending", "on_hold", "paid", "shipped", "returned", "cancelled", "refunded"]

_ALLOWED_TRANSITIONS = {
    "pending": {"on_hold", "paid", "cancelled"},
    "on_hold": {"pending", "cancelled"},
    "paid": {"shipped", "on_hold"},
    "shipped": {"returned"},
    "returned": {"refunded"},
    "cancelled": set(),
    "refunded": set(),
}


def advance(order, target):
    """Move an order to `target`, refusing moves that go backwards."""
    cur = order["state"]
    try:
        cur_lower = cur.lower()
    except AttributeError:
        raise InvalidTransition(str(cur) + " -> " + str(target))

    try:
        target_lower = target.lower()
    except AttributeError:
        raise InvalidTransition(str(cur) + " -> " + str(target))

    if cur_lower not in _ALLOWED_TRANSITIONS or target_lower not in _ALLOWED_TRANSITIONS:
        raise InvalidTransition(str(cur) + " -> " + str(target))

    if target_lower not in _ALLOWED_TRANSITIONS[cur_lower]:
        raise InvalidTransition(str(cur) + " -> " + str(target))

    order["state"] = target_lower
    return order

