filePath: /work/labelsync/tags.py
newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    out = []
    seen_lower = set()

    # Pre-calculate tombstones for each source
    tombstones_at_source = []
    for tags in sources:
        current_tombstones = set()
        for tag in tags:
            if tag.startswith('-'):
                current_tombstones.add(tag[1:].lower())
        tombstones_at_source.append(current_tombstones)

    # Process each source
    for i, tags in enumerate(sources):
        for tag in tags:
            # Skip tombstones in output
            if tag.startswith('-'):
                continue

            tag_lower = tag.lower()

            # Check if this tag is suppressed by any tombstone in a HIGHER precedence source (index < i)
            suppressed = False
            for h in range(i):
                if tag_lower in tombstones_at_source[h]:
                    suppressed = True
                    break

            if suppressed:
                continue

            # If not suppressed and not already seen (case-insensitively), include it
            if tag_lower not in seen_lower:
                seen_lower.add(tag_lower)
                out.append(tag)

    return out

