newString: """Config quantity parsing for the provisioning pipeline."""


def parse_quantity(value, kind):
    """Convert a config quantity like '512M' into bytes for the given
    resource kind ("memory" or "disk")."""
    s = str(value).strip()
    if not s:
        raise ValueError("empty quantity value")

    if s[-1].isalpha():
        suffix = s[-1].upper()
        num_str = s[:-1]
        orig_suffix_char = s[-1]
    else:
        suffix = "M" if kind == "memory" else "G"
        num_str = s
        orig_suffix_char = None

    if kind == "memory":
        multipliers = {"K": 1024, "M": 1024 ** 2, "G": 1024 ** 3, "T": 1024 ** 4}
    elif kind == "disk":
        multipliers = {"M": 1000 ** 2, "G": 1000 ** 3, "T": 1000 ** 4}
    else:
        raise ValueError("unknown resource kind: " + str(kind))

    if suffix not in multipliers:
        suffix_char_to_show = orig_suffix_char if orig_suffix_char is not None else suffix
        raise ValueError("invalid unit suffix for " + kind + ": " + suffix_char_to_show)

    val = int(num_str)
    return val * multipliers[suffix]

